"""Checks the ATO column. Usage: python3 tools/ato-test.py [screenshot_dir]"""
import base64, subprocess, sys, time, os
from playwright.sync_api import sync_playwright
R = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
FX = R + '/tests/fixtures/beartrap/'
b64 = lambda n: base64.b64encode(open(FX + n, 'rb').read()).decode()
shots = sys.argv[1] if len(sys.argv) > 1 else None
srv = subprocess.Popen([sys.executable, '-m', 'http.server', '8768', '--directory', R], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL); time.sleep(1)
ok = True
def check(name, cond):
    global ok; ok &= bool(cond); print('OK  ' if cond else 'FAIL', name)
try:
    with sync_playwright() as p:
        br = p.chromium.launch(); pg = br.new_page(viewport={'width': 1700, 'height': 1300}, reduced_motion='reduce'); errs = []
        import dialogs; dialogs.install(pg)
        pg.on('pageerror', lambda e: errs.append(str(e)))
        pg.goto('http://localhost:8768/app/index.html'); pg.wait_for_timeout(800)
        pg.click('[data-t=kb]')
        check('empty ATO message before a campaign', 'Select a campaign' in pg.inner_text('#ato'))
        pg.evaluate("""async(b)=>{const f=(s,n)=>new File([Uint8Array.from(atob(s),c=>c.charCodeAt(0))],n);await __app.loadCam(f(b,'x.cam'))}""", b64('PSI_BEAR_TRAP_26.cam'))
        pg.wait_for_timeout(600); check('a freshly opened campaign is already in the Close all state: Open all offered, one package shown (the selected flight\'s)', 'Open all' in pg.inner_text('#aq_tog') and pg.locator('#ato .pk').count() == 1 and pg.locator('#ato .fl.sel').count() == 1)
        pg.locator('#ato .ph').first.click(); pg.wait_for_timeout(400)
        check('first click on the selected package only folds it (the whole mission does not open)', pg.locator('#ato .ph').count() == 1)
        pg.locator('#ato .ph').first.click(); pg.wait_for_timeout(400)
        check('faction button uses the program green', pg.evaluate("getComputedStyle(document.getElementById('aq_viewb')).backgroundColor") == 'rgb(76, 195, 138)')
        check('selected flight opened its category and package', pg.locator('#ato .fl.sel').count() == 1)
        pg.locator('#ato .ct:has-text("▸")').first.click(); pg.wait_for_timeout(400)
        check('opening another mission shows all its packages, the selected one stays restricted to its package', pg.locator('#ato .ct:has-text("▾")').count() == 2 and pg.locator('#ato .pk').count() > 3 and pg.locator('#ato .fl.sel').count() == 1 and pg.locator('#ato .pk:has(.fl.sel)').count() == 1)
        per = "()=>{const o={};let c=null;document.querySelectorAll('#ato .ct, #ato .pk').forEach(e=>{if(e.classList.contains('ct')){c=e.textContent.replace(/[▸▾]/g,'').trim();o[c]=0}else if(c)o[c]++});return o}"
        before = pg.evaluate(per); sel_cat = pg.evaluate("()=>{let c=null,r=null;document.querySelectorAll('#ato .ct, #ato .pk').forEach(e=>{if(e.classList.contains('ct'))c=e.textContent.replace(/[▸▾]/g,'').trim();else if(e.querySelector('.fl.sel'))r=c});return r}")
        other = pg.locator('#ato .ct:has-text("▾")').last; other_name = other.inner_text().replace('▾', '').strip()
        for i in range(pg.locator('#ato .ct:has-text("%s") ~ .pk' % other_name.split(' (')[0]).count()):
            pg.locator('#ato .ct:has-text("%s") ~ .pk .ph' % other_name.split(' (')[0]).nth(i).click(); pg.wait_for_timeout(300)
            if pg.evaluate("()=>{let c=null,r=null;document.querySelectorAll('#ato .ct, #ato .pk').forEach(e=>{if(e.classList.contains('ct'))c=e.textContent.replace(/[▸▾]/g,'').trim();else if(e.querySelector('.fl.sel'))r=c});return r}") != sel_cat: break
        after = pg.evaluate(per)
        check('selecting a flight in another mission leaves the first mission restricted to its package (%s)' % sel_cat, sel_cat and after.get(sel_cat) == before.get(sel_cat) == 1)
        pg.wait_for_timeout(500)
        check('player faction preselected and marked', '(you)' in pg.inner_text('#aq_view option:checked'))
        check('no all-factions / category selects', pg.locator('#aq_team,#aq_cat,#aq_me').count() == 0)
        check('theater selector and calendar moved to the top bar', pg.locator('#kbtop #d1').count() == 1 and pg.locator('#kbtop #tsel').count() == 1 and pg.is_visible('#kbtop'))
        check('package mission is green', pg.locator('#ato .ph .ms').count() > 0)
        opened = pg.locator('#ato .ph .ar:text("▾")').count(); fcount = pg.evaluate("()=>__app.F.pk0_0")
        pg.locator('#ato .ct:has-text("▾")').first.click()
        check('closing a mission closes its packages', pg.locator('#ato .ph .ar:text("▾")').count() < opened or opened == 0)
        check('datacard stays filled', bool(pg.evaluate("()=>__app.F.pk0_0")))
        for _ in range(8):
            c = pg.locator('#ato .ct:has-text("▸")')
            if c.count() == 0: break
            c.first.click()
        check('allied packages shown in violet', pg.locator('#ato .pk.al').count() > 0)
        # --- manual datacard changes are remembered per flight ---
        ta = "#form textarea >> nth=0"; setv = lambda v: pg.evaluate("v=>{const e=document.querySelector('#form textarea');e.value=v;e.dispatchEvent(new Event('input',{bubbles:true}))}", v)
        pg.evaluate("()=>{document.getElementById('fsel').value=0;__app.apply(0)}"); pg.wait_for_timeout(300)
        auto0 = pg.input_value(ta); setv('MY NOTE'); pg.wait_for_timeout(200)
        check('an edited field is marked and the Reset button appears', 'man' in (pg.get_attribute(ta, 'class') or '').split() and pg.is_visible('#rstf'))
        pg.evaluate("()=>{document.getElementById('fsel').value=1;__app.apply(1)}"); pg.wait_for_timeout(300)
        check('another flight fills in by itself: no manual text, no Reset button', pg.input_value(ta) != 'MY NOTE' and not pg.is_visible('#rstf'))
        pg.evaluate("()=>{document.getElementById('fsel').value=0;__app.apply(0)}"); pg.wait_for_timeout(300)
        check('coming back to the first flight brings the manual change back', pg.input_value(ta) == 'MY NOTE' and pg.is_visible('#rstf'))
        pg.once('dialog', lambda d: d.dismiss()); pg.evaluate("()=>{const d=document.getElementById('d1');d.value='2031-01-01';d.dispatchEvent(new Event('change'))}"); pg.wait_for_timeout(500)
        check('changing the date asks first; Cancel keeps the date and the changes', pg.input_value(ta) == 'MY NOTE' and pg.input_value('#d1') != '2031-01-01')
        pg.once('dialog', lambda d: d.accept()); pg.evaluate("()=>{const d=document.getElementById('d1');d.value='2031-01-01';d.dispatchEvent(new Event('change'))}"); pg.wait_for_timeout(600)
        check('OK applies the new date and throws the manual changes away', pg.input_value(ta) != 'MY NOTE' and not pg.is_visible('#rstf'))
        setv('AGAIN'); pg.once('dialog', lambda d: d.accept()); pg.click('#rstf'); pg.wait_for_timeout(500)
        check('Reset datacard fills the flight in again', pg.input_value(ta) != 'AGAIN' and not pg.is_visible('#rstf'))
        print('     violet packages:', pg.locator('#ato .pk.al').count())
        cats = pg.locator('#ato .ct').count(); check('mission categories listed (%d)' % cats, cats >= 2)
        pg.locator('#ato .ct').first.click(); pg.locator('#ato .ct').first.click()
        pg.locator('#ato .ct').first.click(); check('category toggles', True)
        n = pg.locator('#ato .ph').count()
        dl = []; pg.on('dialog', lambda d: (dl.append(d.message), d.accept()))
        other = pg.evaluate("()=>[...document.querySelectorAll('#aq_view option')].find(o=>!o.textContent.includes('(you)')).value")
        pg.select_option('#aq_view', other); check('other faction shows the warning', len(dl) == 1 and 'not part of this faction' in dl[0])
        check('other faction list is red/locked', pg.locator('#ato .lkw').count() == 1)
        pg.locator('#ato .ct').first.click(); pg.locator('#ato .ph').first.click()
        check('locked flights are not selectable', pg.locator('#ato .fl:not(.nc)').count() == 0 and pg.locator('#ato .fl.sel').count() == 0)
        pg.select_option('#aq_view', pg.evaluate("()=>[...document.querySelectorAll('#aq_view option')].find(o=>o.textContent.includes('(you)')).value"))
        def mixed_in(v):
            pg.select_option('#aq_view', v)
            for _ in range(8):
                c = pg.locator('#ato .ct:has-text("▸")')
                if c.count() == 0: break
                c.first.click()
            return set(pg.evaluate("()=>[...document.querySelectorAll('#ato .ph')].filter(d=>d.textContent.includes(' + ')).map(d=>d.textContent.match(/Pkg (\\d+)/)[1])"))
        opts = pg.evaluate("()=>[...document.querySelectorAll('#aq_view option')].map(o=>o.value)")
        sets = [mixed_in(v) for v in opts]
        allm = set().union(*sets); check('mixed-faction packages exist (%d)' % len(allm), len(allm) > 0)
        check('mixed packages appear in more than one faction', any(sum(1 for x in sets if k in x) >= 2 for k in allm))
        pg.select_option('#aq_view', pg.evaluate("()=>[...document.querySelectorAll('#aq_view option')].find(o=>o.textContent.includes('(you)')).value"))
        dim = pg.evaluate("()=>{const p=[...document.querySelectorAll('#ato .pk')].find(k=>k.querySelector('.ph').textContent.includes(' + '));if(!p)return 1;p.querySelector('.ph').click();return [...document.querySelectorAll('#ato .pk')].find(k=>k.querySelector('.ph').textContent.includes(' + ')).querySelectorAll('.fl:not(.nc)').length}")
        check('allied F-16 flights of a mixed package are selectable (%s)' % dim, dim >= 0)
        pg.fill('#aq_ac', 'F-16'); m = pg.locator('#ato .ph').count(); check('search opens categories (%d packages)' % m, m > 0)
        check('one button: Close all while something is open', 'Close all' in pg.inner_text('#aq_tog'))
        pg.click('#aq_tog'); pg.wait_for_timeout(400); check('after closing the button offers Open all', 'Open all' in pg.inner_text('#aq_tog'))
        pg.click('#aq_tog'); pg.wait_for_timeout(400); check('Open all opens missions and packages', pg.locator('#ato .ph').count() > 0 and pg.locator('#ato .fl').count() > 0)
        SC = "(()=>{let p=document.querySelector('#atolist');while(p&&p!==document.body){const o=getComputedStyle(p).overflowY;if((o=='auto'||o=='scroll')&&p.scrollHeight>p.clientHeight)return p;p=p.parentElement}return document.scrollingElement})()"
        mx = pg.evaluate("(()=>{const s=%s;s.scrollTop=s.scrollHeight;const m=s.scrollTop;s.scrollTop=Math.round(m*0.6);return m})()" % SC); y0 = pg.evaluate("%s.scrollTop" % SC)
        pg.evaluate("(()=>{const f=[...document.querySelectorAll('#ato .fl:not(.nc)')];const t=f[Math.floor(f.length/2)];t.click()})()"); pg.wait_for_timeout(500)
        y1 = pg.evaluate("%s.scrollTop" % SC)
        check('clicking a flight keeps the scroll position of the list (%d -> %d, max %d)' % (y0, y1, mx), mx == 0 or abs(y1 - y0) <= 6)
        sel = pg.locator('#ato .fl.sel').count() > 0; pg.click('#aq_tog'); pg.wait_for_timeout(400); check('Close all clears the search and keeps only the package and mission of the selected flight (%s)' % ('a flight is selected' if sel else 'no flight selected'), pg.locator('#ato .ph').count() == (1 if sel else 0) and pg.input_value('#aq_ac') == '' and 'Open all' in pg.inner_text('#aq_tog') and (not sel or pg.locator('#ato .ct').count() > 1))
        check('flight/package count shown', 'flights' in pg.inner_text('#aq_info'))
        check('the count is a button that hides and shows the search filters', pg.is_visible('#aq_cs')); pg.click('#aq_info'); pg.wait_for_timeout(400); h1 = not pg.is_visible('#aq_cs'); pg.click('#aq_info'); pg.wait_for_timeout(400); check('search filters toggled by the count button', h1 and pg.is_visible('#aq_cs'))
        check('Faction is a button named after the selected faction', '(you)' in pg.inner_text('#aq_viewb')); pg.click('#aq_viewb'); pg.wait_for_timeout(300); check('it opens the faction list', pg.locator('.ddp .ddi').count() >= 2); pg.keyboard.press('Escape'); pg.wait_for_timeout(300)
        pg.fill('#aq_ac', ''); pg.fill('#aq_cs', 'zzzzz'); check('no match message', 'No flight matches' in pg.inner_text('#atolist'))
        pg.fill('#aq_cs', ''); pg.locator('#ato .ct').first.click()
        tm = pg.evaluate("()=>document.querySelector('#ato .ph .m').textContent.match(/TO (\\d\\d:\\d\\d)/)[1]")
        pg.fill('#aq_to', tm.replace(':', '')); a = pg.locator('#ato .ph').count(); check('take off search without colon (%s -> %d)' % (tm, a), a > 0)
        pg.fill('#aq_to', tm); check('take off search with colon', pg.locator('#ato .ph').count() == a)
        pg.fill('#aq_to', ''); pg.fill('#aq_tot', '2359'); check('TOT search', pg.locator('#ato .ph').count() < n or pg.locator('#ato .ph').count() == 0)
        pg.fill('#aq_tot', '')
        pg.fill('#aq_ap', 'zzzz'); check('airport search (no match)', pg.locator('#ato .ph').count() == 0); pg.fill('#aq_ap', '')
        pg.fill('#aq_sq', 'zzzz'); check('squadron search (no match)', pg.locator('#ato .ph').count() == 0); pg.fill('#aq_sq', '')
        pg.fill('#aq_ac', 'F-16')
        one = pg.evaluate("() => [...document.querySelectorAll('#ato .ph')].findIndex(d => d.textContent.includes(' 1 flight') && !d.textContent.includes(' 1 flights'))")
        check('a single-flight F-16 package exists', one >= 0)
        if one >= 0:
            if pg.locator('#ato .ph').nth(one).locator('.ar:text("▾")').count(): pg.locator('#ato .ph').nth(one).click()
            pg.locator('#ato .ph').nth(one).click(); pg.wait_for_timeout(300)
            check('single-flight package click fills the datacard', pg.locator('#ato .fl.sel').count() == 1)
            pg.locator('#ato .ph').nth(one).click(); pg.wait_for_timeout(200)
            check('second click closes the package', pg.locator('#ato .fl.sel').count() == 0)
            check('datacard stays filled after closing', bool(pg.evaluate("()=>__app.F.pk0_0")))
        pg.evaluate('()=>__app.toggleForm()'); pg.evaluate('()=>__app.toggleForm()'); check('layout toggle still works', pg.is_visible('#ato'))
        if shots: pg.screenshot(path=shots + '/ato.png')
        ph0 = pg.evaluate("()=>document.getElementById('aq_cs').placeholder")
        pg.click('[data-t=mp]'); pg.wait_for_timeout(700)
        ph1 = pg.evaluate("()=>({cs:document.getElementById('aq_cs').placeholder,ac:document.getElementById('aq_ac').placeholder,to:document.getElementById('aq_to').placeholder,val:document.getElementById('aq_cs').value})")
        check('on the map the filter fields show the selected flight (%s)' % ph1, ph1['cs'] != 'Callsign' and ph1['val'] == '' and ph1['ac'] != 'Aircraft')
        pg.click('[data-t=kb]'); pg.wait_for_timeout(400)
        check('on the datacard page they are the plain hints again', pg.evaluate("()=>document.getElementById('aq_cs').placeholder") == 'Callsign')
        pg.click('[data-t=mp]'); pg.wait_for_timeout(400)
        tm = pg.evaluate("()=>({t:document.getElementById('mptm').textContent,p:document.getElementById('mptm').parentNode.id})")
        check('campaign time (hour only) sits with the coordinates', tm['p'] == 'mpll' and ':' in tm['t'] and 'Day' not in tm['t'])
        pg.click('[data-t=kb]'); pg.wait_for_timeout(300)
        opts = pg.evaluate("()=>[...document.querySelectorAll('#csel option')].map(o=>o.value)")
        check('mission file extension is short', pg.evaluate("()=>__app.missionExt") == '.bcrd')
        check('no page errors', not errs); [print(e) for e in errs]
        br.close()
finally:
    srv.terminate()
sys.exit(0 if ok else 1)
